func (this *DateTime) GetArrow(widget int64) int32 {
	this.UpdateControl()
	var adj_value int32 = int32(gtk.GTKGtk_adjustment_get_value(gtk.GTKGtk_spin_button_get_adjustment(widget)))
	var new_value int32 = 0
	if this.IsDate() {
		var firstField *jrt.FieldPosition = this.GetNextField(nil)
		var firstFieldConstant int32 = DateTimeGetCalendarField(firstField)
		new_value = this.calendar.Get(DateTimeGetCalendarField(firstField))
		if firstFieldConstant == jrt.CalendarMONTH {
			if (this.style & SHORT) != 0 {
				adj_value--
			} else {
				if (this.style&MEDIUM) != 0 || (this.style&SWTLONG) != 0 {
					if adj_value == 0 {
						return 0
					} else {
						var cond567 int32
						if adj_value > 0 {
							cond567 = ARROW_UP
						} else {
							cond567 = ARROW_DOWN
						}
						return cond567
					}
				}
			}
		}
	} else {
		if this.IsTime() {
			new_value = this.GetHours()
			if this.HasAmPm() {
				if this.GetHours() > 12 {
					new_value = this.GetHours() - 12
				}
				if new_value == 0 {
					new_value = 12
				}
			}
		}
	}
	if adj_value == 0 && this.firstTime {
		return 0
	}
	this.firstTime = false
	if adj_value == new_value {
		return 0
	}
	var cond568 int32
	if adj_value > new_value {
		cond568 = ARROW_UP
	} else {
		cond568 = ARROW_DOWN
	}
	return cond568
}

